import * as T from 'three';

export class Effects{
 clear(){
  this.life.fill(0);this.p.fill(-1000);this.points.geometry.attributes.position.needsUpdate=true;
  for(const r of this.rings){r.age=-1;r.m.visible=false;}
  for(const item of this.lines){this.scene.remove(item.line);item.line.geometry.dispose();item.line.material.dispose();}this.lines.length=0;
  this.lightAge.fill(0);for(const light of this.lights)light.intensity=0;
 }
 constructor(scene,city,intensity){this.scene=scene;this.city=city;this.intensity=intensity;this.cursor=0;this.N=3000;this.life=new Float32Array(this.N);this.age=new Float32Array(this.N);this.p=new Float32Array(this.N*3);this.vel=new Float32Array(this.N*3);this.base=new Float32Array(this.N*3);this.color=new Float32Array(this.N*3);this.p.fill(-1000);const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(this.p,3));g.setAttribute('color',new T.BufferAttribute(this.color,3));const c=document.createElement('canvas');c.width=c.height=32;const q=c.getContext('2d'),a=q.createRadialGradient(16,16,0,16,16,16);a.addColorStop(0,'white');a.addColorStop(.18,'#ffffffe0');a.addColorStop(1,'#ffffff00');q.fillStyle=a;q.fillRect(0,0,32,32);this.points=new T.Points(g,new T.PointsMaterial({size:.13,map:new T.CanvasTexture(c),vertexColors:true,transparent:true,blending:T.AdditiveBlending,depthWrite:false}));this.points.frustumCulled=false;scene.add(this.points);this.lightAge=new Float32Array(4);this.lights=Array.from({length:4},()=>{const l=new T.PointLight(0xff2fa2,0,5,2);scene.add(l);return l;});this.rings=Array.from({length:40},()=>{const m=new T.Mesh(new T.TorusGeometry(1,.025,4,48),new T.MeshBasicMaterial({color:0xffffff,transparent:true,depthWrite:false,blending:T.AdditiveBlending}));m.rotation.x=Math.PI/2;m.visible=false;scene.add(m);return{m,age:-1,size:1};});this.lines=[];this.flash=0;}
 sparks(pos,color,count=28,strength=1,velocity=null){const rgb=new T.Color(color);for(let j=0;j<Math.round(count*this.intensity);j++){const i=this.cursor++%this.N,k=i*3;this.p[k]=pos.x;this.p[k+1]=pos.y+.25;this.p[k+2]=pos.z;const a=Math.random()*Math.PI*2,s=(1+Math.random()*4)*strength;this.vel[k]=Math.cos(a)*s+(velocity?.x??0)*.05;this.vel[k+1]=(1+Math.random()*4)*strength;this.vel[k+2]=Math.sin(a)*s+(velocity?.z??0)*.05;this.age[i]=0;this.life[i]=.25+Math.random()*.65;this.base[k]=rgb.r;this.base[k+1]=rgb.g;this.base[k+2]=rgb.b;}}
 ring(pos,color,size=1){const r=this.rings.find(x=>x.age<0);if(!r)return;r.age=0;r.size=size;r.m.position.copy(pos);r.m.position.y+=.08;r.m.material.color.set(color);r.m.visible=true;}
 impact(pos,color,major=false){this.sparks(pos,color,major?110:32,major?1.25:1);this.ring(pos,color,major?2.5:.65);const i=this.flash++%4;this.lights[i].position.copy(pos);this.lights[i].position.y+=.6;this.lights[i].color.set(color);this.lightAge[i]=.16;}
 arc(a,b,color,branches=3){if(this.lines.length>45)return;const points=[],length=a.distanceTo(b),n=Math.max(7,Math.ceil(length*4));for(let i=0;i<=n;i++){const t=i/n;points.push(new T.Vector3().lerpVectors(a,b,t).add(new T.Vector3((Math.random()-.5)*.48,(Math.random()-.5)*.4+.5,(Math.random()-.5)*.48).multiplyScalar(Math.sin(t*Math.PI))));}const line=new T.Line(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color,transparent:true,opacity:1,blending:T.AdditiveBlending}));this.scene.add(line);this.lines.push({line,age:0});for(let i=0;i<branches;i++){const p=points[2+Math.floor(Math.random()*(n-3))];if(p)this.arc(p,p.clone().add(new T.Vector3((Math.random()-.5)*1.5,Math.random(),(Math.random()-.5)*1.5)),color,0);}}
 tick(dt){for(let i=0;i<this.N;i++){if(this.life[i]<=0)continue;const k=i*3;this.age[i]+=dt;if(this.age[i]>=this.life[i]){this.life[i]=0;this.p[k+1]=-1000;continue;}const oldX=this.p[k],oldZ=this.p[k+2];this.vel[k+1]-=dt*12;this.p[k]+=this.vel[k]*dt;this.p[k+1]+=this.vel[k+1]*dt;this.p[k+2]+=this.vel[k+2]*dt;const floor=this.city.height(this.p[k],this.p[k+2],this.p[k+1])+.045;if(this.p[k+1]<floor){this.p[k+1]=floor;this.vel[k+1]=Math.abs(this.vel[k+1])*.38;this.vel[k]*=.75;this.vel[k+2]*=.75;}if(this.city.blocked(this.p[k],this.p[k+2],0)){this.p[k]=oldX;this.p[k+2]=oldZ;this.vel[k]*=-.5;this.vel[k+2]*=-.5;}const fade=(1-this.age[i]/this.life[i])*1.8;for(let c=0;c<3;c++)this.color[k+c]=this.base[k+c]*fade;}this.points.geometry.attributes.position.needsUpdate=true;this.points.geometry.attributes.color.needsUpdate=true;for(let i=0;i<4;i++){this.lightAge[i]=Math.max(0,this.lightAge[i]-dt);this.lights[i].intensity=20*this.lightAge[i]/.16;}for(const r of this.rings)if(r.age>=0){r.age+=dt;r.m.scale.setScalar(Math.max(.01,r.age/.4*r.size));r.m.material.opacity=Math.max(0,1-r.age/.4);if(r.age>.4){r.age=-1;r.m.visible=false;}}for(let i=this.lines.length-1;i>=0;i--){const a=this.lines[i];a.age+=dt;a.line.material.opacity=1-a.age/.2;if(a.age>.2){this.scene.remove(a.line);a.line.geometry.dispose();a.line.material.dispose();this.lines.splice(i,1);}}}
}
